/// Zero-filling decode (GNUstep `getBytes:length:` clamp: short input leaves the rest zero).
pub fn decode_or0<T: WireStruct>(b: &[u8]) -> T {
    if b.len() >= T::SIZE {
        T::read_le(b)
    } else {
        let mut v = vec![0u8; T::SIZE];
        v[..b.len()].copy_from_slice(b);
        T::read_le(&v)
    }
}
/// Strict decode (`None` if short).
pub fn decode_strict<T: WireStruct>(b: &[u8]) -> Option<T> {
    T::from_slice(b)
}

fn dict(pairs: Vec<(&str, PV)>) -> PV {
    let mut m: GsDict<String, PV> = GsDict::new();
    for (k, v) in pairs {
        m.insert(k.to_string(), v);
    }
    PV::dict(m)
}

fn xml_packet(ty: u8, v: &PV) -> Vec<u8> {
    // The helper failing logs and yields nil; `appendData:nil` appends nothing, so the bare type goes out.
    let body = plist_xml(v).unwrap_or_default();
    frame(ty, &body)
}
fn gz_packet(ty: u8, v: &PV) -> Vec<u8> {
    let body = plist_gz(v).unwrap_or_default();
    frame(ty, &body)
}

