/// 0x12 pickup request.
pub fn pickup_request(requester: u64, ids: &[u64]) -> Vec<u8> {
    let mut w = Wr::with_type(t::CLIENT_PICKUP_REQUEST);
    w.u64(requester);
    for i in ids {
        w.u64(*i);
    }
    w.finish()
}
/// 0x10 fill request with optional XML plist tail.
pub fn fill_request(r: &FillNetRequest, tail: Option<&PV>) -> Vec<u8> {
    let mut v = struct_packet(t::CLIENT_FILL_REQUEST, r);
    if let Some(p) = tail {
        v.extend(plist_xml(p).unwrap_or_default());
    }
    v
}
